<?php $listLabels=$tab==='users'?['active'=>'Aktywne','banned'=>'Zablokowane']:['draft'=>'Szkic','published'=>'Opublikowany','scheduled'=>'Zaplanowany']; ?>
<form method="get" class="list-filters" role="search"><input type="hidden" name="tab" value="<?=e($tab)?>"><label><span class="sr-only"><?=e(le_text('Szukaj na liście'))?></span><input class="input" type="search" name="q" maxlength="80" value="<?=e($listing['q'])?>" placeholder="<?=e(le_text($tab==='users'?'Szukaj po loginie lub e-mailu…':'Szukaj po tytule lub adresie…'))?>"></label><label><span class="sr-only"><?=e(le_text('Filtr statusu'))?></span><select class="input" name="status"><option value=""><?=e(le_text('Wszystkie statusy'))?></option><?php foreach($listLabels as $key=>$label):?><option value="<?=e($key)?>" <?=$listing['status']===$key?'selected':''?>><?=e(le_text($label))?></option><?php endforeach;?></select></label><button class="btn" type="submit"><?=e(le_text('Filtruj'))?></button><?php if($listing['q']!==''||$listing['status']!==''):?><a class="text-link" href="<?=e(admin_url($tab))?>"><?=e(le_text('Wyczyść'))?></a><?php endif;?><small><?=e(le_text('Wyniki:'))?> <?=$listing['total']?></small></form>
